import { WebView } from 'react-native-webview';
import { StyleSheet, View, StatusBar } from 'react-native';
const BASE64_HTML = "";
function atobPolyfill(input) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
  let str = input.replace(/=+$/, '');
  let output = '';
  if (str.length % 4 == 1) throw new Error('Invalid base64');
  for (let bc = 0, bs = 0, buffer, i = 0; (buffer = str.charAt(i++)); ) {
    buffer = chars.indexOf(buffer);
    if (~buffer) {
      bs = bc % 4 ? bs * 64 + buffer : buffer;
      if (bc++ % 4) output += String.fromCharCode(255 & (bs >> ((-2 * bc) & 6)));
    }
  }
  return output;
}
export default function App() {
  const html = atobPolyfill(BASE64_HTML);
  return (
    <View style={styles.container}>
      <StatusBar hidden />
      <WebView originWhitelist={['*']} source={{ html }} style={{ flex: 1 }} javaScriptEnabled={true} domStorageEnabled={true} allowFileAccess={true} allowUniversalAccessFromFileURLs={true} mixedContentMode="always" scalesPageToFit={false} overScrollMode="never" />
    </View>
  );
}
const styles = StyleSheet.create({ container: { flex: 1, backgroundColor: '#000' }, });
